        if line=='---': break
        if ':' in line and not line.startswith(' '):
            k,v=line.split(':',1); front[k.strip()]=v.strip().strip('"')
        elif line.startswith('  -') and 'source_pdf' in front and not front['source_pdf']:
            front['source_pdf']='list'
    miss=required-{k for k,v in front.items() if v}
    if miss or '/mnt/' in text or '/tmp/' in text or row['code_id']=='DNV-OS-F101':
        problems.append((row, sorted(miss)))
print('created', len(created), 'problems', problems[:10])
