        for pat in patterns:
            if pat and pat in line:
                violations.append((f,i,pat))
                break
print('changed_files', len(files))
print('violations', len(violations))
for item in violations[:50]:
    print('%s:%s: %s' % item)
sys.exit(1 if violations else 0)
